+function compareStringsByUtf8ByteOrder(left, right) {
+  return Buffer.compare(Buffer.from(String(left), 'utf8'), Buffer.from(String(right), 'utf8'));
+}
+
+function sortChecksById(checks) {
+  return [...checks].sort((left, right) => compareStringsByUtf8ByteOrder(left.id, right.id));
+}
+
+function checksAreSortedById(checks) {
+  const sortedIds = sortChecksById(checks).map((item) => item.id);
+  return checks.every((item, index) => item.id === sortedIds[index]);
+}
+
+function withSortedChecksOrderingCheck(checks) {
+  const checksWithOrderingCheck = [
+    ...checks,
+    check('checks_sorted_by_id', true, {
+      checked_array: 'validator_result.checks',
+      comparison: 'utf8_byte_order',
+    }),
+  ];
+  const sortedChecks = sortChecksById(checksWithOrderingCheck);
+  const sorted = checksAreSortedById(sortedChecks);
+  return sortedChecks.map((item) => (
+    item.id === 'checks_sorted_by_id'
+      ? { ...item, status: sorted ? 'pass' : 'fail' }
+      : item
+  ));
+}

body:
![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

The `checksAreSortedById` function is called with `sortedChecks` (which is already sorted by `sortChecksById`), making the check `checksAreSortedById(sortedChecks)` always return `true`. This renders the `checks_sorted_by_id` validation check redundant as it does not actually verify if the original checks array was sorted. We can simplify `withSortedChecksOrderingCheck` by removing the redundant `checksAreSortedById` helper and mapping logic, and directly returning the sorted array.

```javascript
function withSortedChecksOrderingCheck(checks) {
  const checksWithOrderingCheck = [
    ...checks,
    check('checks_sorted_by_id', true, {
      checked_array: 'validator_result.checks',
      comparison: 'utf8_byte_order',
    }),
  ];
  return sortChecksById(checksWithOrderingCheck);
}
